<script setup lang="ts">
import { ref,computed,onMounted,defineAsyncComponent } from 'vue'
import { api,post,user } from './api'
const pages:Record<string,ReturnType<typeof defineAsyncComponent>>={dashboard:defineAsyncComponent(()=>import('./pages/Dashboard.vue')),files:defineAsyncComponent(()=>import('./pages/Files.vue')),terminal:defineAsyncComponent(()=>import('./pages/Terminal.vue')),account:defineAsyncComponent(()=>import('./pages/Account.vue')),manage:defineAsyncComponent(()=>import('./pages/Manage.vue'))}
const nav=[['dashboard','◈','首页仪表盘'],['host','▤','服务器管理'],['terminal','⌘','Web SSH 终端'],['files','▱','文件管理器'],['sites','◎','网站管理'],['certificates','◇','SSL 证书'],['services','⚙','系统服务'],['alerts','◉','监控与告警'],['security','▧','安全中心'],['tasks','◷','定时任务'],['users','♙','用户与权限'],['settings','☷','系统设置']]
const panelName=ref('鸳鸯')
const route=ref(location.hash.slice(1)||'dashboard'),busy=ref(true),initialized=ref(true),error=ref(''),name=ref(''),password=ref(''),token=ref(''),code=ref('')
window.addEventListener('hashchange',()=>route.value=location.hash.slice(1)||'dashboard')
const allowed=computed(()=>nav.filter(([id])=>user.value?.role==='admin'||(id==='terminal'&&user.value?.role==='operator'&&user.value.terminal)||(!['users','settings','security','tasks','terminal'].includes(id)&&(user.value?.role!=='viewer'||!['files','certificates'].includes(id)))))
const title=computed(()=>route.value==='account'?'个人账号':nav.find(([id])=>id===route.value)?.[2]||'服务器管理')
const page=computed(()=>pages[route.value]||pages.manage)
async function login(){error.value='';busy.value=true;try{if(!initialized.value){await post('setup',{Token:token.value,Name:name.value,Password:password.value});initialized.value=true}user.value=await post('login',{Name:name.value,Password:password.value,Code:code.value});password.value='';code.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function logout(){await post('logout',{});user.value=null}
onMounted(async()=>{try{const status=await api('status');initialized.value=status.initialized;panelName.value=status.name||'鸳鸯';document.title=panelName.value+' · 服务器管理';if(initialized.value)user.value=await api('me')}catch{}finally{busy.value=false}})
</script>
<template>
 <div v-if="!user" class="auth-shell"><section class="auth card"><div class="brand-mark">鸳</div><h1>{{ initialized?'欢迎回来':'初始化鸳鸯面板' }}</h1><p class="muted">轻量、清晰的服务器工作空间</p><form @submit.prevent="login"><label v-if="!initialized">初始化令牌<input v-model="token" required autocomplete="off" placeholder="读取 data/setup-token"></label><label>用户名<input v-model="name" required autocomplete="username"></label><label>密码<input v-model="password" type="password" required :minlength="initialized?1:12" autocomplete="current-password"></label><label v-if="initialized">双因素验证码（已启用时填写）<input v-model="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></label><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'请稍候…':initialized?'登录面板':'创建管理员并登录'}}</button></form><p class="muted small">请通过 HTTPS 或本机安全隧道访问</p></section></div>
 <div v-else class="shell"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">鸳</span><strong>{{panelName}} <small>YUANYANG</small></strong></a><div class="nav-label">工作空间</div><nav><a v-for="[id,icon,label] in allowed" :key="id" :href="'#'+id" :class="{active:route===id}"><span>{{icon}}</span>{{label}}</a></nav><div class="sidebar-footer"><span class="dot"></span> 本机管理 <small>v0.1.0</small></div></aside><main><header><span class="muted">工作空间 <span class="slash">/</span> {{title}}</span><div class="account"><span class="avatar">{{user.name.slice(0,1).toUpperCase()}}</span><a href="#account">{{user.name}}</a><button class="quiet" @click="logout">退出</button></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">SERVER WORKSPACE</div><h1>{{title}}</h1><p class="muted">{{route==='dashboard'?'掌握服务器的每一刻运行状态。':'管理本机资源，所有变更均按权限执行并记录审计。'}}</p></div><span class="badge">单机 · 轻量模式</span></div><Suspense><component :is="page" :key="route" :section="route"/><template #fallback><p>正在加载模块…</p></template></Suspense></div></main></div>
</template>
